import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Tenant API v1 — Departments","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Departments | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-departments"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Departments | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-departments"}]]},"headers":[],"relativePath":"api/tenant-v1-departments.md","filePath":"api/tenant-v1-departments.md","lastUpdated":1786228685000}'),r={name:"api/tenant-v1-departments.md"};function n(c,e,s,m,p,i){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tenant-api-v1-—-departments" tabindex="-1">Tenant API v1 — Departments <a class="header-anchor" href="#tenant-api-v1-—-departments" aria-label="Permalink to &quot;Tenant API v1 — Departments&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:departments</code>, plus <code>can:departments.*</code>.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-departments-stats" tabindex="-1">GET <code>/departments/stats</code> <a class="header-anchor" href="#get-departments-stats" aria-label="Permalink to &quot;GET `/departments/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload:</p><p><code>total</code>, <code>active</code>, <code>inactive</code>, <code>with_manager</code>.</p><h2 id="departments-crud" tabindex="-1">Departments CRUD <a class="header-anchor" href="#departments-crud" aria-label="Permalink to &quot;Departments CRUD&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/departments</code></td><td><code>departments.view</code></td></tr><tr><td>GET</td><td><code>/departments/stats</code></td><td><code>departments.view</code></td></tr><tr><td>POST</td><td><code>/departments</code></td><td><code>departments.create</code></td></tr><tr><td>GET</td><td><code>/departments/{department}</code></td><td><code>departments.view</code></td></tr><tr><td>PUT</td><td><code>/departments/{department}</code></td><td><code>departments.update</code></td></tr><tr><td>DELETE</td><td><code>/departments/{department}</code></td><td><code>departments.delete</code></td></tr><tr><td>POST</td><td><code>/departments/{department}/restore</code></td><td><code>departments.restore</code></td></tr><tr><td>DELETE</td><td><code>/departments/{department}/force</code></td><td><code>departments.force.delete</code></td></tr></tbody></table><h3 id="get-departments" tabindex="-1">GET <code>/departments</code> <a class="header-anchor" href="#get-departments" aria-label="Permalink to &quot;GET `/departments`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code> (<code>active</code>|<code>inactive</code>), <code>manager_id</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List visibility is scoped: admins see all; managers see managed departments; others see memberships.</p><h3 id="post-departments" tabindex="-1">POST <code>/departments</code> <a class="header-anchor" href="#post-departments" aria-label="Permalink to &quot;POST `/departments`&quot;">​</a></h3><p>Body: <code>name</code> (required), optional <code>slug</code>, <code>description</code>, <code>status</code>, <code>manager_id</code> (user id), <code>user_ids[]</code>, <code>employee_ids[]</code>.</p><p>Defaults: <code>status=active</code>. Slug is auto-generated from name when omitted.</p><h3 id="put-departments-department" tabindex="-1">PUT <code>/departments/{department}</code> <a class="header-anchor" href="#put-departments-department" aria-label="Permalink to &quot;PUT `/departments/{department}`&quot;">​</a></h3><p>Partial update of the same fields. Sending <code>user_ids</code> / <code>employee_ids</code> replaces memberships.</p><h2 id="manager-members" tabindex="-1">Manager &amp; members <a class="header-anchor" href="#manager-members" aria-label="Permalink to &quot;Manager &amp; members&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>PUT</td><td><code>/departments/{department}/manager</code></td><td><code>departments.assign_manager</code></td></tr><tr><td>POST</td><td><code>/departments/{department}/users</code></td><td><code>departments.manage_members</code></td></tr><tr><td>DELETE</td><td><code>/departments/{department}/users</code></td><td><code>departments.manage_members</code></td></tr><tr><td>POST</td><td><code>/departments/{department}/employees</code></td><td><code>departments.manage_members</code></td></tr><tr><td>DELETE</td><td><code>/departments/{department}/employees</code></td><td><code>departments.manage_members</code></td></tr></tbody></table><p>Manager body: <code>{ &quot;manager_id&quot;: number|null }</code> — must reference a User.</p><p>Member bodies: <code>{ &quot;user_ids&quot;: number[] }</code> or <code>{ &quot;employee_ids&quot;: number[] }</code>.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="get-departments-department-performance" tabindex="-1">GET <code>/departments/{department}/performance</code> <a class="header-anchor" href="#get-departments-department-performance" aria-label="Permalink to &quot;GET `/departments/{department}/performance`&quot;">​</a></h3><p>Permission: <code>departments.view_performance</code> (and policy: admin or department manager).</p><p>Returns member counts, Lead/Task aggregates when those modules are installed, and <code>members_breakdown</code> (linked users with counts; unlinked employees with <code>performance_eligible: false</code>).</p><h2 id="employees-integration" tabindex="-1">Employees integration <a class="header-anchor" href="#employees-integration" aria-label="Permalink to &quot;Employees integration&quot;">​</a></h2><p>When Departments is installed, Employee create/update accepts optional <code>department_ids[]</code> and returns <code>departments[]</code> on resources. Legacy string <code>department</code> remains for backward compatibility.</p>',27)])])}const u=t(r,[["render",n]]);export{h as __pageData,u as default};
